                                           const MCTargetOptions &Options)

using llvm::Target::MCObjectFileInfoCtorFnTy =  MCObjectFileInfo *(*)(MCContext &Ctx,
                                                         bool PIC,
                                                         bool LargeCodeModel)

using llvm::Target::MCSubtargetInfoCtorFnTy =  MCSubtargetInfo *(*)(const Triple &TT,
                                                       StringRef CPU,
                                                       StringRef Features)

